INSERT INTO public.data_train1_review_embeddings VALUES (74, 'Perfect to play with supervised with an adult. The kids really love it. I thought it might be a little slow for them, but nope, it gets their imaginations going. Put a tiny piece of paper on the track and say it''s a pretend penny. Make a cardboard tunnel. Lots of FUN. Battery powered runs for weeks. Just be sure it''s off or you will be buying batteries.', '{"review_date": "2024-08-27", "product_name": "Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+", "product_id": 2, "_node_content": "{\"id_\": \"10a8ca88-250b-4192-a2ff-62fc19e9fb5d\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+\", \"product_id\": 2}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '10a8ca88-250b-4192-a2ff-62fc19e9fb5d', '[0.028029019,0.0061936285,0.016573066,0.010762026,0.0043655057,-0.010940832,0.021709835,-0.054243963,0.015985128,-0.014831418,0.07576876,0.010012682,-0.018570019,-0.010887566,-0.017194474,-0.00046292876,0.013717927,-0.0070799626,-0.018855017,0.013617778,-0.044092774,-0.05102854,-0.010375232,0.00095957617,0.012366368,0.04267019,0.014088809,-0.00024324354,-0.031855345,-0.024256373,0.02255115,-0.03075949,-0.074251324,0.047772218,0.014072623,-0.009956674,0.04070244,0.0068123187,0.028282098,-0.023938643,0.03378281,-0.022050213,0.009190222,-0.003062541