INSERT INTO public.data_train1_review_embeddings VALUES (75, 'These larger-scale Lionel trains are perfect for our kiddos who play more on the rough side. This is the 4th ''version'' of those larger trains we purchased (we already have Polar Express, Diesel Construction, and Toy Story) and it did not disappoint. Great sounds, stays on the track, couplers keep train cars together. Couldn''t ask for more.', '{"review_date": "2024-08-27", "product_name": "Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+", "product_id": 2, "_node_content": "{\"id_\": \"ac2d0d3e-6ee1-43ce-960e-dbc8a6212f79\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+\", \"product_id\": 2}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', 'ac2d0d3e-6ee1-43ce-960e-dbc8a6212f79', '[0.021428043,-0.018622342,0.017214462,0.019101355,0.0041986452,-0.0020698602,-0.0006942608,-0.054201595,0.0071729096,0.00029635962,0.04338801,-0.014285791,-0.02495653,-0.0035872262,0.011511936,0.0037702299,0.030263852,0.0028374114,0.00866384,0.022703439,-0.024441727,-0.03173513,-0.018225031,0.030088926,0.0036111784,0.048801485,0.024774108,0.016050799,-0.008521889,-0.01900223,0.049120024,-0.008740156,-0.09142387,0.03303452,-0.0104323765,0.02148747,0.025353774,0.00067424163,0.005902327,-0.02276651,0.02617962,-0.03211492,0.029400976,0.011360127,-0.027328534,0.01