INSERT INTO public.data_train1_review_embeddings VALUES (81, 'This thing was incredible. It managed to occupy not three, but FOUR toddlers for hours every day for a week as it chugged around the Christmas tree. Judging by the amount of trauma it went through at the hands of the kiddos, it seems pretty difficult to break. Worth every penny.', '{"review_date": "2024-08-27", "product_name": "Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+", "product_id": 2, "_node_content": "{\"id_\": \"84b3446c-0435-4a13-9a84-0ca69461e208\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+\", \"product_id\": 2}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '84b3446c-0435-4a13-9a84-0ca69461e208', '[0.022337588,-0.0020798214,0.044046115,0.008568672,-0.005128786,-0.0067816786,0.0037027746,-0.0034487701,-0.034257207,-0.01620697,0.0631126,0.011352129,-0.0033656585,-0.012250828,-0.012278333,-0.0016468347,0.03050583,-0.012306942,5.0121776e-05,-0.0077539594,-0.018211894,-0.051692747,-0.0022800427,-0.0010159715,-0.005790709,0.062884234,-0.006489311,0.0059807613,-0.0249749,-0.014650243,0.016364036,-0.005161482,-0.09248137,0.038310185,-0.0138084795,0.008250326,-0.017815089,-0.009087218,0.022759482,-0.010017253,0.03877641,-0.044220883,0.0012994558,0.023837302,-0.012224706,0.009418058,0.007746274,-0.02828718,-0.022384938,-0.022