INSERT INTO public.data_train1_review_embeddings VALUES (87, 'Great toy for under the tree. I had three problems with it, though. First, I received the box with impact damage at one corner. Luckily, the toy was not damaged. Second, the toy did not arrive with any instructions. Thirdly, the center detent on the remote forward/reverse throttle tends to wander.', '{"review_date": "2024-08-27", "product_name": "Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+", "product_id": 2, "_node_content": "{\"id_\": \"0bca0740-72fe-408d-88ca-f6e7fbfa76f1\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Lionel Battery-Operated Construction Toy Train Set with Locomotive, Train Cars, Track & Remote with Authentic Train Sounds, & Lights for Kids 4+\", \"product_id\": 2}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '0bca0740-72fe-408d-88ca-f6e7fbfa76f1', '[0.023712197,-0.019673657,0.0041083745,0.030572396,-0.044626743,0.023196595,0.023988731,-0.05898611,-0.008983765,-0.0019668683,0.09518321,0.008099887,0.013418871,0.00969941,-0.018356005,0.009511252,-0.015391209,-0.014711592,-0.014859465,-0.02711849,-0.03316513,-0.05065691,0.011717755,-0.061293047,0.020778183,0.004346403,-0.02315909,-0.018186737,-0.013444791,-0.04064248,0.028602958,0.011104263,-0.0580916,0.028330633,-0.027229518,0.02627221,0.018957388,-0.003049217,0.04585447,0.013135665,0.05473978,-0.04217074,0.025969185,-0.011751837,-0.0393433,0.0150997965,0.02352679,-0.012605986,-0.0420817,-0.005240854,