INSERT INTO public.data_train1_review_embeddings VALUES (129, 'From an appearance standpoint the trains look great. However, trains derail frequently; train to rail alignment is a challenge which is why the track to track connections are critical to trains remaining running. Side Note: the analog connection wire was missing when the Trains were delivered. I contacted the Company''s Customer Service team and their comment was ''Oh, that happens a lot. We will send you a replacement connector''. It never arrived. Also, the Train Controller Unit operates on the function 3 setting but defaults to function 1 anytime there is a derailment or train stoppage. If you are interested in more than appearance keep looking.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"e66f5700-27f0-4de8-a7c1-57dd83c858ae\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', 'e66f5700-27f0-4de8-a7c1-57dd83c858ae', '[0.028132003,-0.0140737565,-0.016629871,0.044511706,-0.019137269,0.0149018355,0.024531053,-0.030606875,-0.0047285967,0.031544417,0.032025766,0.0155894775,-0.005900295,0.027147727,-0.0012328126,0.041849844,-0.013559787,-0.020623045,-0.019760128,0.050404172,-0.044776194,-0.016723644,0.015958304,-0.03297715,0.046722222,0.05419494,0.02076821,-0.03521835,0.0205