INSERT INTO public.data_train1_review_embeddings VALUES (122, 'I love this DCC set. I have had it for 2 years. I have expanded my set on a 5 x 10 board to have 3 oval tracks connected by crossover tracks. I am running 4 trains at one time and it works great. One of my engines has sound and this works great too. I am using the original DCC controller that came with the set. I do not need the 5 amp add-on power that some reviewers think you may need. Bachmann makes quality products at a reasonable price.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"53c6058a-d41d-4a7d-99f2-2a1a44aebe76\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '53c6058a-d41d-4a7d-99f2-2a1a44aebe76', '[0.021238765,-0.016364,0.06518742,0.04275975,0.007224737,0.005757229,0.0016084118,-0.019422254,-0.0035428477,0.016342212,0.038927887,0.008238104,-0.0099652875,0.026553016,-0.014297615,0.019370139,0.013037058,0.0032220515,-0.0044225636,0.031661417,-0.021039087,-0.024797693,0.013197354,0.0073065907,0.027897032,0.045021046,0.021171484,-0.009371831,-0.0013509528,-0.011678235,-0.00056482514,-0.0035549493,-0.10725499,-0.006620845,-0.024085298,-0.06571996,0.0015784055,0.03473951,-0.014182389,-0.048695337,0.02967499,-0.017523663,-0.0046834024,0.012069468,-0.020434737,-0.0