INSERT INTO public.data_train1_review_embeddings VALUES (130, 'A real disappointment. Clever layout with two good-looking locomotives that just don’t perform with the digital control. Very inconsistent operation, buttons switch over randomly to a different function, trains constantly derail. Best to look elsewhere and skip the allure of twin locomotives.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"047a20e6-35cc-437e-9648-8648c0435e76\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '047a20e6-35cc-437e-9648-8648c0435e76', '[0.031007703,-0.013659573,0.021048224,0.050156634,-0.040949177,0.007012958,-0.014044446,-0.034545086,0.01457289,0.025900586,0.01573424,0.013916254,-0.0055478183,0.010810922,-0.023654075,0.031327877,-0.007022022,-0.0031620935,-0.02811497,0.018184679,-0.022173284,-0.021626992,0.01664016,-0.012846573,0.032885298,0.052032534,-0.0054758242,-0.020546969,-0.0041939165,-0.0312999,0.003771809,0.0017690696,-0.083161354,-0.011334084,-0.056664433,-0.04111838,-0.015188689,0.018873116,0.015126922,-0.035747312,0.041651968,-0.019798204,0.0049871975,-0.00036321857,-0.0043030023,0.0093226945,0.0060001337,-0.00965404,-0.035107575,-0.04512872,-0.043355346,-0.042736012,0.04255359,0.013218295,0.004331446,-0.016061524,0.016823007,0.00