INSERT INTO public.data_train1_review_embeddings VALUES (126, 'Had a great time setting it up and once it was all together the 6-year-old it was bought for was able to operate it with no problem. It did take him a while to master setting the trains on the tracks but it was not a problem as they cannot damage anything by attempting to master that skill (pretty much the hardest thing for the little guy to do). Straightforward controls once you read the instructions, you can set up several different engines on the switchboard they provide. It was bought for a Christmas gift and he is still playing with it regularly.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"dc190492-3fdf-43d0-9659-3860a05d415b\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', 'dc190492-3fdf-43d0-9659-3860a05d415b', '[0.01284029,0.006195841,0.033889547,0.025870683,-0.01199541,0.011208288,-0.0021353508,-0.01896711,-0.0050475537,0.0016061392,0.06528078,0.022028204,-0.007345838,0.0069529675,-0.018908951,0.01959648,0.005065573,0.023814254,-0.01789397,0.031492487,-0.039869823,-0.041592754,0.03085208,-0.017306533,0.033255897,0.033861645,-0.016070912,0.0050581405,-0.022495145,-0.022046931,-0.0043868567,-0.0035052418,-0.0877061,0.007519729,0.0033348734,-0.049925648,-0.01459