INSERT INTO public.data_train1_review_embeddings VALUES (132, 'Bought this for my 8-year-old for Christmas. The layout went together fine and the cars and engines seem to run well. Unfortunately, the command controller fried after about 30 minutes of use, I think because of a derailment. We sent it in, and it took a solid 6 weeks to get it fixed/replaced. Luckily, our hobby shop let me borrow a DCC controller until we got our replacement back. So, aside from the quality of the DCC controller, we really like the set.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"53a68baa-a26e-4550-9220-a3a52413b913\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '53a68baa-a26e-4550-9220-a3a52413b913', '[0.014668783,-0.027697535,-0.0027362267,0.012313944,-0.015556696,0.03433802,0.026546545,-0.029084591,-0.02698956,0.021032894,0.057735056,0.008808598,-0.014065132,0.03301979,-0.038288496,0.03240417,-0.02006685,-0.041952148,-0.018644553,0.0066944957,-0.031093258,-0.024336213,0.034202572,-0.031544097,0.031703662,0.06521577,-0.01655703,-0.015731,0.014229486,-0.029099895,0.008991007,0.018259585,-0.044041786,-0.021718465,-0.051310882,-0.06051624,-0.021387573,0.020778678,0.0055362135,-0.011464239,0.021254586,-0.014626577,0.03370127,0.009901614,-0.0059052147