INSERT INTO public.data_train1_review_embeddings VALUES (134, 'The train set was exactly what we needed. Being new to model trains, my son received a DCC sound equipped steam engine for Christmas as well as some Bachmann expansion track. The problem was his existing model train set was an Atlas and didn''t have a DCC controller. The Bachmann track is incompatible with Atlas and he couldn''t use all the functionality of the new engine. So, we decided to switch him from Atlas to Bachman and we found that this train set was the best way to get into Bachmann and a digital command controller. It was available at a great price and works great.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"7fb22889-6b97-4808-9e0c-860a829adb56\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '7fb22889-6b97-4808-9e0c-860a829adb56', '[0.02173265,-0.031129787,0.05749584,0.033047967,-0.00494808,0.018869435,-0.013032576,0.007959509,-0.0042640115,0.03268623,0.040211868,0.019203579,-0.012265382,0.016047072,-0.04671182,0.04163937,0.01081026,0.013063833,-0.010669145,0.019112414,-0.012812643,-0.030194325,0.018047025,-0.01231022,0.033660915,0.034868825,-0.0114456825,-0.01567528,0.0032365008,-0.028876847,0.033292525,-0.002994883,-0.084599294,0.0039757076,-0.019866472,