INSERT INTO public.data_train1_review_embeddings VALUES (136, 'Not even close to worth the price. The lights on both locomotives didn''t work. There is no on-off switch on the power source, so it has to be unplugged. Derailed easily. One car wouldn''t couple. Returned and ordered a Lionel. We''ll see how that goes. Lionel Superchief was the way to go. Very happy with it.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"2bc1ec4b-8aa1-4e15-a95e-b6700204229c\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '2bc1ec4b-8aa1-4e15-a95e-b6700204229c', '[0.020017892,-0.01392468,0.032024834,0.02709532,0.006015533,0.022946019,-0.005826297,-0.044741414,0.0067468067,0.014443335,0.018576479,0.03390785,-0.0009907144,-0.00071679574,-0.0072936714,0.014235806,-0.00858611,0.009213567,-0.025031894,0.00034395233,-0.025987228,-0.026397154,-0.0014011383,-0.01741177,0.018401183,0.044561427,0.006735949,-0.01727915,0.010222658,-0.034490388,0.0038287605,0.005081059,-0.09103512,-0.00033160328,-0.06368767,-0.034946833,-0.00043060255,0.041452803,0.022041995,-0.04752015,0.045222994,-0.04272339,-0.019059112,0.018322583,0.0029349346,-0.0026430176,0.0062766974,-0.024443267,-0.03657212,-0.03795312,-0.032884665,-0.0658004,0.07355022,0.013286388,0.010687122,-0.019729262,-