INSERT INTO public.data_train1_review_embeddings VALUES (143, 'We purchased this set as a gift for our 9-year-old son. One of the trains was broken right out of the box. I considered returning the whole thing to Amazon, but since one train did work, we decided to keep it and just return the one broken train to Bachmann. What a mistake! Bachmann says it will take 6 weeks to replace the train. 6 weeks to replace something that was broken right out of the box. THIS IS UNACCEPTABLE! Bachmann should immediately replace the defective train. I should have sent the whole thing back to Amazon for a full refund. No Bachmann trains this Xmas - their Customer Service is terrible.', '{"review_date": "2024-08-27", "product_name": "Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale", "product_id": 1, "_node_content": "{\"id_\": \"27c4d625-a36a-4a6e-b52e-08c34ece1351\", \"embedding\": null, \"metadata\": {\"review_date\": \"2024-08-27\", \"product_name\": \"Bachmann Trains - Digital Commander DCC Equipped Ready To Run Electric Train Set - HO Scale\", \"product_id\": 1}, \"excluded_embed_metadata_keys\": [], \"excluded_llm_metadata_keys\": [], \"relationships\": {}, \"text\": \"\", \"mimetype\": \"text/plain\", \"start_char_idx\": null, \"end_char_idx\": null, \"text_template\": \"{metadata_str}\\n\\n{content}\", \"metadata_template\": \"{key}: {value}\", \"metadata_seperator\": \"\\n\", \"class_name\": \"TextNode\"}", "_node_type": "TextNode", "document_id": "None", "doc_id": "None", "ref_doc_id": "None"}', '27c4d625-a36a-4a6e-b52e-08c34ece1351', '[0.013215368,0.008759611,0.05300927,0.018276088,-0.033149157,0.047145884,-0.008534726,-0.052181967,-0.01288739,0.032311242,0.003950477,0.034125376,0.0025559529,0.012034786,-0.035344496,0.027661795,-0.025456026,-0.02830159,-0.045312725,-0.014667562,-0.044655718,-0.029203543,0.036984716,0.031564094,-0.003568593,0.038035445,-0.010472011,-0.0031838655,0.024894897,-0.0075531225,0.023723932,0.0059118285,